     1	package com.pousada.report.generators;
     2	
     3	import com.pousada.domain.model.Reservation;
     4	import com.pousada.domain.model.Room;
     5	import com.pousada.infrastructure.repository.RoomRepository;
     6	import com.pousada.report.ReportGenerator;
     7	
     8	import java.time.LocalDate;
     9	import java.util.List;
    10	
    11	public class OccupancyReportGenerator implements ReportGenerator {
    12	
    13	    @Override
    14	    public String getName() {
    15	        return "occupancy";
    16	    }
    17	
    18	    @Override
    19	    public String generate(String period, List<Reservation> reservations, RoomRepository roomRepository) {
    20	        LocalDate date = LocalDate.parse(period);
    21	
    22	        List<Reservation> occupiedReservations = reservations.stream()
    23	            .filter(Reservation::isPaid)
    24	            .filter(r -> r.occupiesNight(date))
    25	            .sorted((r1, r2) -> r1.getRoomNumber().compareTo(r2.getRoomNumber()))
    26	            .toList();
    27	
    28	        StringBuilder csv = new StringBuilder();
    29	        csv.append("Pousada Maré Alta,").append(getName()).append(",").append(period).append("\n");
    30	        csv.append("room,type,reservation,check_in,check_out\n");
    31	
    32	        for (Reservation reservation : occupiedReservations) {
    33	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    34	            csv.append(reservation.getRoomNumber()).append(",")
    35	               .append(room.getType()).append(",")
    36	               .append(reservation.getId()).append(",")
    37	               .append(reservation.getCheckIn()).append(",")
    38	               .append(reservation.getCheckOut()).append("\n");
    39	        }
    40	
    41	        int totalRooms = roomRepository.getTotalRooms();
    42	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
    43	
    44	        return csv.toString();
    45	    }
    46	}
