     1	package com.pousada.report.generators;
     2	
     3	import com.pousada.domain.model.RatePlan;
     4	import com.pousada.domain.model.Reservation;
     5	import com.pousada.infrastructure.repository.RoomRepository;
     6	import com.pousada.report.ReportGenerator;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.YearMonth;
    10	import java.util.List;
    11	import java.util.Map;
    12	import java.util.stream.Collectors;
    13	
    14	public class RatePlansReportGenerator implements ReportGenerator {
    15	
    16	    @Override
    17	    public String getName() {
    18	        return "rate-plans";
    19	    }
    20	
    21	    @Override
    22	    public String generate(String period, List<Reservation> reservations, RoomRepository roomRepository) {
    23	        YearMonth month = YearMonth.parse(period);
    24	
    25	        List<Reservation> monthReservations = reservations.stream()
    26	            .filter(r -> {
    27	                YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
    28	                return checkInMonth.equals(month);
    29	            })
    30	            .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
    31	            .toList();
    32	
    33	        Map<RatePlan, List<Reservation>> byPlan = monthReservations.stream()
    34	            .collect(Collectors.groupingBy(Reservation::getRatePlan));
    35	
    36	        StringBuilder csv = new StringBuilder();
    37	        csv.append("Pousada Maré Alta,").append(getName()).append(",").append(period).append("\n");
    38	        csv.append("rate_plan,reservations,amount\n");
    39	
    40	        int totalReservations = 0;
    41	        BigDecimal totalAmount = BigDecimal.ZERO;
    42	
    43	        for (RatePlan plan : RatePlan.values()) {
    44	            List<Reservation> planReservations = byPlan.getOrDefault(plan, List.of());
    45	            int count = planReservations.size();
    46	            BigDecimal amount = planReservations.stream()
    47	                .map(Reservation::getNetAmount)
    48	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    49	
    50	            csv.append(plan).append(",")
    51	               .append(count).append(",")
    52	               .append(formatDecimal(amount)).append("\n");
    53	
    54	            totalReservations += count;
    55	            totalAmount = totalAmount.add(amount);
    56	        }
    57	
    58	        csv.append("total,").append(totalReservations).append(",").append(formatDecimal(totalAmount));
    59	
    60	        return csv.toString();
    61	    }
    62	
    63	    private String formatDecimal(BigDecimal value) {
    64	        return value.setScale(2).toPlainString();
    65	    }
    66	}
