     1	package com.pousada.domain.service;
     2	
     3	import com.pousada.infrastructure.repository.ReservationRepository;
     4	import com.pousada.infrastructure.repository.RoomRepository;
     5	import com.pousada.report.ReportGenerator;
     6	
     7	import java.util.HashMap;
     8	import java.util.Map;
     9	
    10	public class ReportService {
    11	    private final Map<String, ReportGenerator> generators = new HashMap<>();
    12	    private final ReservationRepository reservationRepository;
    13	    private final RoomRepository roomRepository;
    14	
    15	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    16	        this.reservationRepository = reservationRepository;
    17	        this.roomRepository = roomRepository;
    18	    }
    19	
    20	    public void registerGenerator(ReportGenerator generator) {
    21	        generators.put(generator.getName(), generator);
    22	    }
    23	
    24	    public String generateReport(String reportName, String period) {
    25	        ReportGenerator generator = generators.get(reportName);
    26	        if (generator == null) {
    27	            throw new IllegalArgumentException("Unknown report: " + reportName);
    28	        }
    29	
    30	        return generator.generate(period, reservationRepository.findAll(), roomRepository);
    31	    }
    32	}
