253	public class ReservationService {
254	    private final ReservationRepository reservationRepository;
255	    private final RoomService roomService;
256	
257	    public ReservationService(ReservationRepository reservationRepository, RoomService roomService) {
258	        this.reservationRepository = reservationRepository;
259	        this.roomService = roomService;
