356	package com.pousada.domain.pricing;
357	
358	import com.pousada.domain.model.RatePlan;
359	import com.pousada.domain.model.RoomType;
360	
361	import java.math.BigDecimal;
362	import java.math.RoundingMode;
363	import java.time.LocalDate;
364	
365	public class PricingCalculator {
366	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
367	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
368	
369	    public static BigDecimal calculateNightPrice(RoomType roomType, LocalDate night) {
370	        BigDecimal basePrice = roomType.getNightlyRate();
371	
372	        if (SeasonCalculator.isHighSeason(night)) {
373	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
374	        }
375	
376	        return roundHalfToEven(basePrice);
377	    }
378	
379	    public static BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
380	        BigDecimal subtotal = BigDecimal.ZERO;
381	        LocalDate current = checkIn;
382	
383	        while (current.isBefore(checkOut)) {
384	            BigDecimal nightPrice = calculateNightPrice(roomType, current);
385	            subtotal = subtotal.add(nightPrice);
386	            current = current.plusDays(1);
387	        }
388	
389	        return roundHalfToEven(subtotal);
390	    }
391	
392	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
393	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
394	            return roundHalfToEven(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
395	        }
396	        return BigDecimal.ZERO;
397	    }
398	
399	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
400	        return roundHalfToEven(subtotal.subtract(discount));
401	    }
402	
403	    public static BigDecimal calculateTourismTax(int guests, int nights) {
404	        BigDecimal taxPerGuestPerNight = new BigDecimal("4.50");
405	        return taxPerGuestPerNight.multiply(BigDecimal.valueOf(guests))
406	                                  .multiply(BigDecimal.valueOf(nights));
407	    }
408	
409	    private static BigDecimal roundHalfToEven(BigDecimal value) {
410	        return value.setScale(2, RoundingMode.HALF_EVEN);
411	    }
412	}
