418	public class SeasonCalculator {
419	
420	    public static boolean isHighSeason(LocalDate date) {
421	        int day = date.getDayOfMonth();
422	        Month month = date.getMonth();
423	
424	        if (month == Month.JULY) {
425	            return true;
426	        }
427	
428	        if (month == Month.DECEMBER && day >= 15) {
429	            return true;
430	        }
431	
432	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
433	            return true;
434	        }
435	
436	        return false;
437	    }
438	}
