447	
448	public class ReservationValidator {
449	
450	    public static void validateDates(LocalDate checkIn, LocalDate checkOut) {
451	        if (!checkOut.isAfter(checkIn)) {
452	            throw new ValidationException("INVALID_REQUEST", "Check-out must be after check-in");
453	        }
454	    }
455	
456	    public static void validateGuests(int guests, Room room) {
457	        if (guests < 1) {
458	            throw new ValidationException("INVALID_REQUEST", "At least one guest is required");
459	        }
460	        if (guests > room.getCapacity()) {
461	            throw new ValidationException("CAPACITY_EXCEEDED",
462	                "Room capacity is " + room.getCapacity() + " but " + guests + " guests requested");
463	        }
464	    }
465	
466	    public static void validateRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut,
467	                                               List<Reservation> existingReservations) {
468	        LocalDate current = checkIn;
469	        while (current.isBefore(checkOut)) {
470	            if (!existingReservations.isEmpty()) {
471	                throw new ValidationException("ROOM_UNAVAILABLE",
472	                    "Room " + roomNumber + " is not available for the requested dates");
473	            }
474	            current = current.plusDays(1);
475	        }
476	    }
477	
478	    public static void validateConfirmation(Reservation reservation) {
479	        if (reservation.getStatus() != ReservationStatus.PENDING) {
480	            throw new ValidationException("OPERATION_NOT_ALLOWED",
481	                "Only pending reservations can be confirmed");
482	        }
483	    }
484	
485	    public static void validateCheckIn(Reservation reservation) {
486	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
487	            throw new ValidationException("OPERATION_NOT_ALLOWED",
488	                "Only confirmed reservations can be checked in");
489	        }
490	    }
491	
492	    public static void validateCheckOut(Reservation reservation) {
493	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
494	            throw new ValidationException("OPERATION_NOT_ALLOWED",
