262	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
263	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
264	                                        int guests, RatePlan ratePlan) {
265	        Room room = roomService.getRoomByNumber(roomNumber);
266	
267	        ReservationValidator.validateDates(checkIn, checkOut);
268	        ReservationValidator.validateGuests(guests, room);
269	
270	        LocalDate current = checkIn;
271	        while (current.isBefore(checkOut)) {
272	            List<Reservation> conflicting = reservationRepository
273	                .findActiveByRoomAndNight(roomNumber, current);
274	            ReservationValidator.validateRoomAvailability(roomNumber, checkIn, checkOut, conflicting);
275	            current = current.plusDays(1);
