277	
278	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
279	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getType(), checkIn, checkOut);
280	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
281	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
