465	
466	    public static void validateRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut,
467	                                               List<Reservation> existingReservations) {
468	        LocalDate current = checkIn;
469	        while (current.isBefore(checkOut)) {
470	            if (!existingReservations.isEmpty()) {
